const $=s=>document.querySelector(s);
const theme=$('#theme');
let savedTheme;try{savedTheme=localStorage.getItem('ras-theme')}catch{}
function setTheme(value){document.documentElement.dataset.theme=value;theme.setAttribute('aria-pressed',String(value==='light'));theme.setAttribute('aria-label',value==='dark'?'切换到浅色主题':'切换到深色主题');document.querySelector('meta[name=theme-color]').content=value==='dark'?'#12131f':'#eeebf4'}
setTheme(savedTheme==='light'?'light':'dark');theme.onclick=()=>{const value=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(value);try{localStorage.setItem('ras-theme',value)}catch{}};
const modal=$('#modal');function show(content){$('#modal-content').innerHTML=content;modal.showModal()}$('.close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const posts=[['第一夜 / 夜间手记','初めて夜に一人で外に出た。','assets/manga-page-11.jpg'],['片段收藏 / よふかしのうた','今日に満足できるまで、夜ふかししてみろよ。','assets/manga-page-6.jpg']];
document.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>{const p=posts[Number(b.dataset.post)];show(`<span class="mini-label">${p[0]}</span><h2>${p[1]}</h2><img src="${p[2]}" alt="原漫画试读画面"><p>《彻夜之歌》台词收藏 · 随笔占位</p>`)});
