let toastTimer;function toast(text){$('.toast').textContent=text;$('.toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),3000)}document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>toast(`${b.dataset.social} 联系方式尚未填写`));
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-15% 0px -50% 0px'});document.querySelectorAll('#home,#about,#notes,#works,#contact').forEach(s=>observer.observe(s));
let lastStar=0;document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||matchMedia('(prefers-reduced-motion: reduce)').matches||Date.now()-lastStar<90)return;lastStar=Date.now();const s=document.createElement('span');s.className='cursor-star';s.textContent='✧';s.style.left=e.clientX+'px';s.style.top=e.clientY+'px';document.body.append(s);s.addEventListener('animationend',()=>s.remove())});
// Original quiet synthesized pads; no copyrighted audio or pretend playback.
const tracks=[{name:'Midnight walk',notes:[130.81,155.56,196,233.08]},{name:'Lavender clouds',notes:[110,130.81,164.81,196]},{name:'Before the dawn',notes:[146.83,174.61,220,261.63]}];
let ctx,master,voices=[],playing=false,track=0,position=0,last=0;const duration=180;
function stopVoices(){voices.forEach(o=>{try{o.stop()}catch{}});voices=[]}
async function audio(){ctx??=new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();master??=ctx.createGain();master.gain.value=Number($('#volume').value);master.connect(ctx.destination);stopVoices();tracks[track].notes.forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f;o.detune.value=i%2?4:-4;g.gain.setValueAtTime(0,ctx.currentTime);g.gain.linearRampToValueAtTime(.065,ctx.currentTime+2);o.connect(g);g.connect(master);o.start();voices.push(o)})}
function update(){document.body.classList.toggle('playing',playing);$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'暂停氛围音':'播放氛围音');$('#track-name').textContent=tracks[track].name;$('#progress').value=position;$('#elapsed').textContent=Math.floor(position/60)+':'+String(Math.floor(position%60)).padStart(2,'0')}
$('#play').onclick=async()=>{try{if(playing){await ctx.suspend();playing=false}else{await audio();playing=true;last=performance.now()}update()}catch{toast('当前浏览器暂不支持音频播放')}};
async function changeTrack(delta){track=(track+delta+tracks.length)%tracks.length;position=0;if(playing)await audio();update()}
$('#previous').onclick=()=>changeTrack(-1);$('#next').onclick=()=>changeTrack(1);$('#progress').oninput=e=>{position=Number(e.target.value);update()};$('#volume').oninput=()=>{if(master)master.gain.value=Number($('#volume').value);$('#mute').setAttribute('aria-label',Number($('#volume').value)===0?'取消静音':'静音')};let previousVolume=.35;$('#mute').onclick=()=>{const v=$('#volume');if(Number(v.value)){previousVolume=Number(v.value);v.value=0}else v.value=previousVolume||.35;v.oninput();$('#mute').textContent=Number(v.value)?'♫':'♪'};
setInterval(()=>{const now=performance.now();if(playing){position+=(now-last)/1000;if(position>=duration)changeTrack(1);update()}last=now},250);
